    /**
     * Tests creating a new DeviceCertificate.
     *
     * @return    DeviceCertificate
     */
    public DeviceCertificate testCreate() throws Throwable {
    DeviceCertificate entity = null;

    LOGGER.info( "DeviceCertificateTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a DeviceCertificate");

    StringBuilder msg = new StringBuilder( "-- Failed to create a DeviceCertificate" );

    try {
        entity = service.createDeviceCertificate( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getDeviceCertificateId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a DeviceCertificate with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a DeviceCertificate.
     *
     * @return    DeviceCertificate
     */
    public DeviceCertificate testRead() throws Throwable {
    LOGGER.info( "DeviceCertificateTest:testRead()" );
    LOGGER.info( "-- Reading a previously created DeviceCertificate" );

    DeviceCertificate entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read DeviceCertificate with primary key" );
    msg.append( theId );

    try {
        entity = service.getDeviceCertificate( new DeviceCertificateFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getDeviceCertificateId();

        LOGGER.info( "-- Successfully found DeviceCertificate " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a DeviceCertificate.
     *
     * @return    DeviceCertificate
     */
    public DeviceCertificate testUpdate() throws Throwable {
    LOGGER.info( "DeviceCertificateTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a DeviceCertificate." );

    StringBuilder msg = new StringBuilder( "Failed to update a DeviceCertificate : " );
    DeviceCertificate entity = null;

    try {
        UpdateDeviceCertificateCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setDeviceCertificateId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created DeviceCertificate." );

        entity = service.updateDeviceCertificate( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved DeviceCertificate - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a DeviceCertificate.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "DeviceCertificateTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created DeviceCertificate." );

    try {
        DeleteDeviceCertificateCommand deleteCommand = new DeleteDeviceCertificateCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted DeviceCertificate with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete DeviceCertificate with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all DeviceCertificates.
     *
     * @return    Collection
     */
    public List<DeviceCertificate> testGetAll() throws Throwable {
    LOGGER.info( "DeviceCertificateTest:testGetAll() - Retrieving Collection of DeviceCertificates:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all DeviceCertificate : " );
    List<DeviceCertificate> collection  = null;

    try {
        // call the static get method on the DeviceCertificateService
        collection = service.getAllDeviceCertificate();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            DeviceCertificate currEntity  = null;
            Iterator<DeviceCertificate> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDeviceCertificateId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

